/// A video a user uploaded. Shown on the author's profile and in the Explore feed.
class VideoPost {
  final String id;
  final String authorId;
  final String authorName;
  final String authorUsername;

  /// Asset path, file path or URL of the author's photo.
  final String authorAvatar;

  /// File path on this device (local mode) or URL on the server.
  final String videoUrl;

  /// Optional poster image URL generated by the server.
  final String? thumbnailUrl;
  final String caption;
  final DateTime createdAt;
  final int likes;
  final int views;

  const VideoPost({
    required this.id,
    required this.authorId,
    required this.authorName,
    required this.authorUsername,
    required this.authorAvatar,
    required this.videoUrl,
    this.thumbnailUrl,
    this.caption = '',
    required this.createdAt,
    this.likes = 0,
    this.views = 0,
  });

  factory VideoPost.fromJson(Map<String, dynamic> json) => VideoPost(
    id: json['id'] as String,
    authorId: json['authorId'] as String? ?? '',
    authorName: json['authorName'] as String? ?? 'Tivoo user',
    authorUsername: json['authorUsername'] as String? ?? 'tivoo_user',
    authorAvatar: json['authorAvatar'] as String? ?? '',
    videoUrl: json['videoUrl'] as String,
    thumbnailUrl: json['thumbnailUrl'] as String?,
    caption: json['caption'] as String? ?? '',
    createdAt: DateTime.tryParse(json['createdAt'] as String? ?? '') ?? DateTime.now(),
    likes: (json['likes'] as num?)?.toInt() ?? 0,
    views: (json['views'] as num?)?.toInt() ?? 0,
  );

  Map<String, dynamic> toJson() => {
    'id': id,
    'authorId': authorId,
    'authorName': authorName,
    'authorUsername': authorUsername,
    'authorAvatar': authorAvatar,
    'videoUrl': videoUrl,
    'thumbnailUrl': thumbnailUrl,
    'caption': caption,
    'createdAt': createdAt.toIso8601String(),
    'likes': likes,
    'views': views,
  };

  /// "1.2K" style view count for tiles.
  String get formattedViews {
    if (views >= 1000000) return '${(views / 1000000).toStringAsFixed(1)}M';
    if (views >= 1000) return '${(views / 1000).toStringAsFixed(1)}K';
    return '$views';
  }
}

/// Who is uploading. Until login works this is the local profile plus a device id.
class PostAuthor {
  final String id;
  final String name;
  final String username;
  final String avatar;

  const PostAuthor({required this.id, required this.name, required this.username, required this.avatar});
}
